152	328      public static long choose(long n, long k) {
153	329          if (k > n / 2) k = n - k;
154	330          if (k == 0) return 1;
155	331          if (k == 1) return n;
156	332          // k <= n/2
157	333          // Will multiply (k) terms, n-k+1 through n-k+k
158	334          // will divide by k terms, 1 through k
159	335          // Note that if we divide after multiplying, it will
160	336          // always be evenly divisible.
161	337          // Proof: when we divide by k, we've multiplied by k consecutive integers,
162	338          // at least one of which will be a multiple of k.
163	339          long accum = 1;
164	340          for (long j = 1; j <= k; j++) {
165	341              long m = n - k + j;
166	342              accum = accum * m;
167	343              accum = accum / j;
168	344          }
169	345          return accum;
170	346      }
